```powershell
# Define the root directory and output CSV path
$root = 'C:\AI\benchmark\v2\results-v3\sandboxes\knight__off\term-log-rapor'
$outputCsv = Join-Path $root 'rapor.csv'

# Find all .log files (exact extension case-insensitive)
$logFiles = Get-ChildItem -Recurse -Path $root | Where-Object { $_.Extension.ToLower() -eq '.log' }

# Prepare the results array
$results = @()

foreach ($file in $logFiles) {
    if (-not (Test-Path $file.FullName)) {
        Write-Warning "File not found: $($file.FullName)"
        continue
    }

    # Initialize counts for each log file
    $errorCount = 0
    $warnCount = 0
    $infoCount = 0

    try {
        [System.IO.File]::OpenText($file.FullName) | ForEach-Object {
            $line = $_.Trim()
            if ($line -and $line.Split() | Where-Object { $_.Count -ge 3 }) {
                $parts = @('' ) + $_.Split().GetEnumerator() | ${...}.ToArray()
                # Check third element (index 2)
                if ([string]::IsNullOrWhiteSpace($parts[2])) { }
                else {
                    $msgUpper = $parts[2].ToUpper()
                    switch ($msgUpper) {
                        'ERROR'      { $errorCount++ }
                        'WARN'       { $warnCount++ }
                        'INFO'       { $infoCount++ }
                    }
                }
            }
        }
    } catch {
        Write-Warning "Error reading file: $($file.FullName) $_"
    }

    # Add the current log file's results to the array
    $results += [PSCustomObject]@{
        dosya = $file.FullName
        error = $errorCount
        warn = $warnCount
        info = $infoCount
    }
}

# Export the collected data to CSV without type information (to prevent PowerShell encoding issues)
$results | Export-Csv -Path $outputCsv -NoTypeInformation

Write-Output "CSV report created at: $($outputCsv)"
